function Index() {
  useEffect(() => {
    const nav = document.getElementById("nav");
    const onScroll = () => {
      nav?.classList.toggle("scrolled", window.scrollY > 40);
    };
    window.addEventListener("scroll", onScroll);

    const anchorLinks = Array.from(document.querySelectorAll<HTMLAnchorElement>('a[href^="#"]'));
    const onAnchorClick = (e: Event) => {
      const a = e.currentTarget as HTMLAnchorElement;
      const target = document.querySelector(a.getAttribute("href") ?? "");
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    };
    anchorLinks.forEach((a) => a.addEventListener("click", onAnchorClick));

    function animateCounter(el: HTMLElement) {
      const target = parseFloat(el.dataset["target"] ?? "0");
      const isDecimal = (el.dataset["target"] ?? "").includes(".");
      const duration = 2000;
      const start = performance.now();
      const update = (now: number) => {
        const t = Math.min((now - start) / duration, 1);
        const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
        el.textContent = isDecimal
          ? (ease * target).toFixed(1)
          : Math.round(ease * target).toLocaleString("en-IN");
        if (t < 1) requestAnimationFrame(update);
      };
      requestAnimationFrame(update);
    }

    const counterObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.querySelectorAll<HTMLElement>("[data-target]").forEach(animateCounter);
            counterObserver.unobserve(e.target);
          }
        });
      },
      { threshold: 0.3 },
    );
    document.querySelectorAll(".impact-grid").forEach((el) => counterObserver.observe(el));

    const submitBtn = document.querySelector<HTMLButtonElement>("#form-submit-btn");
    const errorEl = document.querySelector<HTMLParagraphElement>("#form-error");
    const nameEl = document.querySelector<HTMLInputElement>("#enq-name");
    const phoneEl = document.querySelector<HTMLInputElement>("#enq-phone");
    const emailEl = document.querySelector<HTMLInputElement>("#enq-email");
    const businessTypeEl = document.querySelector<HTMLSelectElement>("#enq-business-type");
    const needEl = document.querySelector<HTMLSelectElement>("#enq-need");
    const messageEl = document.querySelector<HTMLTextAreaElement>("#enq-message");
    const botcheckEl = document.querySelector<HTMLInputElement>("#botcheck");

    const showError = (msg: string) => {
      if (!errorEl) return;
      errorEl.textContent = msg;
      errorEl.style.display = "block";
    };
    const hideError = () => {
      if (!errorEl) return;
      errorEl.style.display = "none";
    };

    const onSubmitClick = async () => {
      if (!submitBtn) return;
      hideError();

      if (botcheckEl?.checked) return; // spam bot honeypot

      const name = nameEl?.value.trim() ?? "";
      const email = emailEl?.value.trim() ?? "";
      if (!name || !email) {
        showError("Please fill in your name and email address.");
        return;
      }

      const accessKey = import.meta.env["VITE_WEB3FORMS_ACCESS_KEY"] as string | undefined;
      if (!accessKey) {
        showError(
          "This form isn't fully configured yet — please email operations@aarkin.co.in directly.",
        );
        return;
      }

      const originalLabel = submitBtn.textContent;
      submitBtn.disabled = true;
      submitBtn.textContent = "Sending…";

      try {
        const res = await fetch("https://api.web3forms.com/submit", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({
            access_key: accessKey,
            subject: "New Enquiry — Aarkin Website",
            from_name: name,
            name,
            phone: phoneEl?.value.trim() ?? "",
            email,
            business_type: businessTypeEl?.value ?? "",
            need: needEl?.value ?? "",
            message: messageEl?.value.trim() ?? "",
          }),
        });
        const data = await res.json();

        if (data.success) {
          submitBtn.textContent = "✓ Request Submitted — We'll reach out within 4 hours!";
          submitBtn.style.background = "#0d6e3b";
          if (nameEl) nameEl.value = "";
          if (phoneEl) phoneEl.value = "";
          if (emailEl) emailEl.value = "";
          if (businessTypeEl) businessTypeEl.value = "";
          if (needEl) needEl.value = "";
          if (messageEl) messageEl.value = "";
          setTimeout(() => {
            submitBtn.textContent = originalLabel;
            submitBtn.style.background = "";
            submitBtn.disabled = false;
          }, 5000);
        } else {
          showError("Something went wrong sending your request. Please try again.");
          submitBtn.textContent = originalLabel;
          submitBtn.disabled = false;
        }
      } catch {
        showError("Network error — please check your connection and try again.");
        submitBtn.textContent = originalLabel;
        submitBtn.disabled = false;
      }
    };
    submitBtn?.addEventListener("click", onSubmitClick);

    return () => {
      window.removeEventListener("scroll", onScroll);
      anchorLinks.forEach((a) => a.removeEventListener("click", onAnchorClick));
      counterObserver.disconnect();
      submitBtn?.removeEventListener("click", onSubmitClick);
    };
  }, []);

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: SITE_STYLES }} />
      <div dangerouslySetInnerHTML={{ __html: SITE_BODY_HTML }} />
    </>
  );
}
